      user: 'ユーザー・グループ', proc: 'プロセス・ジョブ', svc: 'サービス・ログ（systemd）', sched: '定期実行・予約', pkg: 'パッケージ管理',
      net: 'ネットワーク', remote: 'リモート接続・転送', fw: 'ファイアウォール', disk: 'ディスク・ファイルシステム', lvm: 'LVM',
